CREATE DATABASE IF NOT EXISTS webhosting_admin CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE webhosting_admin;
CREATE TABLE IF NOT EXISTS customers(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,name VARCHAR(190) NOT NULL,email VARCHAR(190),address VARCHAR(255),postcode VARCHAR(20),city VARCHAR(120),phone VARCHAR(50),status ENUM('active','inactive','blocked') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS projects(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,customer_id BIGINT UNSIGNED NULL,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL,status ENUM('active','disabled') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_projects_slug(slug)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS domains(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,project_id BIGINT UNSIGNED NULL,domain VARCHAR(253) NOT NULL,status ENUM('active','pending','disabled') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_domains_domain(domain)) ENGINE=InnoDB;

ALTER TABLE customers MODIFY status ENUM('active','inactive','blocked') NOT NULL DEFAULT 'active';

SET @db=DATABASE();
SET @sql=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='customers' AND COLUMN_NAME='address')=0,'ALTER TABLE customers ADD COLUMN address VARCHAR(255) NULL AFTER email','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='customers' AND COLUMN_NAME='postcode')=0,'ALTER TABLE customers ADD COLUMN postcode VARCHAR(20) NULL AFTER address','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='customers' AND COLUMN_NAME='city')=0,'ALTER TABLE customers ADD COLUMN city VARCHAR(120) NULL AFTER postcode','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='customers' AND COLUMN_NAME='phone')=0,'ALTER TABLE customers ADD COLUMN phone VARCHAR(50) NULL AFTER city','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
